void test_event_lifecycle_real_profile_sequence(){
 auto s=game();TestAccess::reset(s);TestAccess::deck(s,1,{"TEST_FILLER"});
 check(s.diagnostic_trace().empty(),"diagnostic trace is empty by default");s.set_trace_enabled(true);
 TestAccess::minion(s,0,"CATA_475",3,6);TestAccess::minion(s,0,"CATA_999",4,4);
 TestAccess::minion(s,1,"CORE_DRG_107",2,1);TestAccess::minion(s,1,"POOL_LOW_B",1,1);
 s.apply_action({ActionType::EndTurn});
 const auto& trace=s.diagnostic_trace();check(std::any_of(trace.begin(),trace.end(),[](const auto& row){return row.starts_with("ACTION ");}),"diagnostic trace records actions");check(std::any_of(trace.begin(),trace.end(),[](const auto& row){return row.starts_with("DEATH ")&&row.find("CORE_DRG_107")!=std::string::npos;}),"diagnostic trace identifies dying card instance");check(std::any_of(trace.begin(),trace.end(),[](const auto& row){return row.starts_with("DEATHRATTLE ")&&row.find("CORE_DRG_107")!=std::string::npos;}),"diagnostic trace records deathrattle resolution");
 check(TestAccess::player(s,1).hero_health==24,"two real end-turn triggers both damage the enemy hero");
 check(TestAccess::player(s,1).board.empty(),"area trigger removes the simultaneous lethal set");
 auto owner=s.observation(1);
 check(std::count_if(owner.self_hand.begin(),owner.self_hand.end(),[](const auto& c){return c.card_id=="EX1_277";})==1,"Violet Spellwing deathrattle generates exactly one Arcane Missiles");
 auto hidden=s.observation(0);
 check(std::none_of(hidden.self_hand.begin(),hidden.self_hand.end(),[](const auto& c){return c.card_id=="EX1_277";})&&hidden.opponent.hand_size==2,"generated identity stays hidden from the opponent");
 s.validate_invariants();auto branch=s.clone();const auto copied_trace_size=branch->diagnostic_trace().size();s.set_trace_enabled(false);check(s.diagnostic_trace().empty()&&branch->diagnostic_trace().size()==copied_trace_size,"clone owns an independent diagnostic trace buffer");branch->set_trace_enabled(true);auto actions=s.semantic_legal_actions();
 auto missile=std::find_if(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PlayCard&&a.card_id=="EX1_277";});
 check(missile!=actions.end(),"generated spell returns through ordinary legal-action generation");
 s.apply_action(*missile);branch->apply_action(*missile);auto left=s.observation(1),right=branch->observation(1);
 check(left.self_player.hero_health==right.self_player.hero_health&&left.opponent.hero_health==right.opponent.hero_health,"cloned generated-card RNG branches produce the same visible hero state");
 check(left.opponent.board.size()==right.opponent.board.size()&&std::equal(left.opponent.board.begin(),left.opponent.board.end(),right.opponent.board.begin(),[](const auto& a,const auto& b){return a.card_id==b.card_id&&a.current_health==b.current_health;}),"cloned generated-card RNG branches produce the same visible board");
 s.validate_invariants();branch->validate_invariants();
}
