 TestAccess::reset(s);TestAccess::hand(s,0,"JAIL_801");TestAccess::hand(s,0,"CORE_EX1_145");TestAccess::hand(s,0,"CORE_EX1_145");TestAccess::hand(s,0,"CORE_EX1_129");TestAccess::hand(s,0,"CORE_EX1_145");TestAccess::deck(s,0,{"JAIL_801","TEST_FILLER"});int target=TestAccess::minion(s,1,"POOL_LOW_A",1,5);s.apply_action(play_hand(s,1));s.apply_action(play_hand(s,1));s.apply_action(play_hand(s,1));auto drawn=s.observation(0);check(drawn.self_hand.size()==3&&drawn.self_hand[0].card_id=="JAIL_801t"&&drawn.self_hand[2].card_id=="JAIL_801","effect-drawn later copy starts in spell form after older copy transforms");check(TestAccess::counter(s,0,2,"held_spell_threshold")==0&&drawn.self_hand[2].current_cost==3,"newly drawn copy starts with zero prior spells");auto fresh_branch=s.clone();s.apply_action(play_hand(s,1));check(TestAccess::counter(s,0,1,"held_spell_threshold")==1&&TestAccess::counter(*fresh_branch,0,1,"held_spell_threshold")==0,"same-card instances and cloned branches retain independent progression");

 TestAccess::reset(s);TestAccess::hand(s,0,"JAIL_803");for(int n=0;n<3;++n)TestAccess::hand(s,0,"CORE_EX1_145");TestAccess::deck(s,0,{"TEST_FILLER","TEST_FILLER"});TestAccess::minion(s,0,"POOL_LOW_A",1,3);TestAccess::minion(s,1,"POOL_LOW_B",2,4);for(int n=0;n<3;++n)s.apply_action(play_hand(s,1));TestAccess::player(s,0).mana=10;auto frost_actions=s.semantic_legal_actions();check(std::none_of(frost_actions.begin(),frost_actions.end(),[](const auto& a){return a.type==ActionType::PlayCard&&a.card_id=="JAIL_803t"&&a.target_is_self;}),"transformed Frostshatter excludes friendly characters from Battlecry targets");auto frost=std::find_if(frost_actions.begin(),frost_actions.end(),[](const auto& a){return a.type==ActionType::PlayCard&&a.card_id=="JAIL_803t"&&a.target_entity_id==2;});check(frost!=frost_actions.end(),"transformed Frostshatter offers enemy hero target");s.apply_action(*frost);check(s.observation(1).self_player.hero_frozen&&s.observation(0).self_hand.size()==2,"Frostshatter Elemental freezes enemy hero and draws two");

