 s.apply_action(Action{ActionType::EndTurn});s.apply_action(Action{ActionType::EndTurn});s.validate_invariants();auto next_turn=s.observation(0);check(next_turn.self_hand.size()>=2&&next_turn.self_hand[0].current_cost==3,"Prepare cost reduction persists to a later turn");auto next_actions=s.legal_actions();check(std::any_of(next_actions.begin(),next_actions.end(),[](const auto& a){return a.type==ActionType::PlayCard&&a.hand_index==0;}),"prepared card becomes playable on the next own turn");
 TestAccess::reset(s);TestAccess::hand(s,0,"TEST_PREPARE_SEVEN");TestAccess::player(s,0).mana=3;actions=s.semantic_legal_actions();prepare=std::find_if(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PrepareCard;});check(prepare!=actions.end(),"Prepare is legal when current cost exceeds remaining mana");s.apply_action(*prepare);s.validate_invariants();check(TestAccess::player(s,0).mana==0&&TestAccess::player(s,0).hand[0].cost_delta==-4,"cost 7 with 3 mana spends all 3 and reduces cost by exactly 4");
 TestAccess::reset(s);TestAccess::hand(s,0,"TEST_PREPARE_CHEAP");TestAccess::player(s,0).mana=5;actions=s.semantic_legal_actions();prepare=std::find_if(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PrepareCard;});check(prepare!=actions.end(),"Prepare is offered for a positive-cost unprepared card");s.apply_action(*prepare);s.validate_invariants();check(TestAccess::player(s,0).mana==4&&TestAccess::player(s,0).hand[0].cost_delta==-2&&s.observation(0).self_hand[0].current_cost==0,"cost 2 with 5 mana spends one and reaches zero without wasting four mana");
 s.apply_action(Action{ActionType::EndTurn});s.apply_action(Action{ActionType::EndTurn});actions=s.legal_actions();check(std::any_of(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PlayCard&&a.hand_index==0;}),"zero-cost prepared card is playable next own turn without poisoning legality");check(std::none_of(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PrepareCard&&a.hand_index==0;}),"prepared instance cannot be prepared again");
 TestAccess::reset(s);TestAccess::hand(s,0,"TEST_PREPARE_ZERO");TestAccess::player(s,0).mana=1;actions=s.legal_actions();check(std::none_of(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PrepareCard;}),"zero-cost card remains playable but cannot be Prepared");
 TestAccess::reset(s);TestAccess::hand(s,0,"TEST_PREPARE_ZERO");TestAccess::player(s,0).mana=0;actions=s.semantic_legal_actions();check(std::none_of(actions.begin(),actions.end(),[](const auto& a){return a.type==ActionType::PrepareCard;}),"Prepare requires at least one remaining mana");
