void test_spell_damage_hand_deck_instances(){
 auto s=game();TestAccess::reset(s);TestAccess::hand(s,0,"CATA_458");TestAccess::hand(s,0,"CORE_CS2_029");TestAccess::hand(s,0,"TEST_FILLER");TestAccess::deck(s,0,{"CORE_CS2_024","CATA_489"});s.apply_action(play_hand(s,0));auto obs=s.observation(0);check(obs.self_hand[0].current_spell_damage==1&&obs.self_hand[1].current_spell_damage==0,"Battlecry modifies spell instances in hand and excludes minions");check(obs.self_player.deck_size==2&&obs.opponent.deck_size==0,"deck observation exposes sizes without identities or enchantment values");auto clone=s.clone();TestAccess::minion(s,0,"CORE_EX1_012",1,1);s.apply_action(play(s,2));check(TestAccess::player(s,1).hero_health==22,"card Spell Damage stacks with board Spell Damage when that spell resolves");check(clone->observation(0).self_hand[0].current_spell_damage==1&&clone->observation(1).opponent.hero_health==30,"clone preserves private per-instance modifier state independently");
 TestAccess::reset(s);TestAccess::hand(s,0,"CATA_458");TestAccess::deck(s,0,{"CORE_CS2_029"});s.apply_action(play(s));TestAccess::draw_cards(s,0);obs=s.observation(0);auto drawn=std::find_if(obs.self_hand.begin(),obs.self_hand.end(),[](const auto& c){return c.card_id=="CORE_CS2_029";});check(drawn!=obs.self_hand.end()&&drawn->current_spell_damage==1,"modified deck instance keeps its bonus when drawn");TestAccess::enter(s,0,"CORE_CS2_029");obs=s.observation(0);check(obs.self_hand.back().current_spell_damage==0,"spell entering hand after Battlecry starts without retroactive bonus");
 TestAccess::reset(s);TestAccess::hand(s,0,"CATA_458");TestAccess::deck(s,0,{"CATA_489"});s.apply_action(play(s));TestAccess::hand(s,0,"TEST_FILLER");bool rejected=false;try{TestAccess::draw_cards(s,0);}catch(const UnsupportedSimulationError&){rejected=true;}check(rejected&&!s.is_valid(),"pre-split modifier interaction fails closed rather than asserting invented duplication");
 TestAccess::reset(s);TestAccess::hand(s,0,"TEST_SPELL_DAMAGE_HAND_DECK");TestAccess::hand(s,0,"CORE_CS2_029");s.apply_action(play_hand(s,0));check(s.observation(0).self_hand[0].current_spell_damage==2,"shared Battlecry contract honors a second declaration parameter without ID behavior");
}
